// Auth: Register (No phone numbers required!)
app.post('/api/auth/register', (req: Request, res: Response) => {
  const { username, displayName, password, publicKeyJwk, bio } = req.body;

  if (!username || !displayName || !password) {
    return res.status(400).json({ error: 'Username, display name, and password are required.' });
  }

  const cleanUsername = username.toLowerCase().replace(/[^a-z0-9_]/g, '');
  if (cleanUsername.length < 3) {
    return res.status(400).json({ error: 'Username ID must be at least 3 characters (letters, numbers, underscore).' });
  }

  // Check unique username
  const existing = Object.values(db.users).find((u: any) => u.username === cleanUsername);
  if (existing) {
    return res.status(400).json({ error: 'Username handle is already taken. Please choose another ID.' });
  }

  const userId = `usr_${Math.random().toString(36).substring(2, 10)}`;
  const avatarColors = [
    'from-emerald-500 to-teal-600',
    'from-indigo-500 to-cyan-600',
    'from-rose-500 to-pink-600',
    'from-amber-500 to-orange-600',
    'from-violet-500 to-purple-600',
    'from-blue-500 to-sky-600',
  ];
  const avatarColor = avatarColors[Math.floor(Math.random() * avatarColors.length)];

  const newUser = {
    id: userId,
    username: cleanUsername,
    displayName,
    avatarColor,
    bio: bio || 'CipherGram private encrypted user',
    publicKeyJwk: publicKeyJwk || null,
    twoFactorEnabled: false,
    twoFactorSecret: null,
    backupCodes: [],
    passwordHash: password, // In production, bcrypt hash; simple password comparison for portable storage
    createdAt: Date.now(),
    lastSeen: Date.now(),
  };

  db.users[userId] = newUser;
  saveDb();

  res.json({
    user: {
      id: newUser.id,
      username: newUser.username,
      displayName: newUser.displayName,
      avatarColor: newUser.avatarColor,
      bio: newUser.bio,
      publicKeyJwk: newUser.publicKeyJwk,
      twoFactorEnabled: newUser.twoFactorEnabled,
      createdAt: newUser.createdAt,
    },
    token: `token_${userId}_${Date.now()}`,
  });
});

// Auth: Login
app.post('/api/auth/login', (req: Request, res: Response) => {
  const { username, password, totpToken } = req.body;
  if (!username || !password) {
    return res.status(400).json({ error: 'Username and password are required.' });
  }

  const cleanUsername = username.toLowerCase().replace(/[^a-z0-9_]/g, '');
  const user = Object.values(db.users).find(
    (u: any) => u.username === cleanUsername || u.id === username
  );

  if (!user || user.passwordHash !== password) {
    return res.status(401).json({ error: 'Invalid username or password.' });
  }

  // Check 2FA
  if (user.twoFactorEnabled) {
    if (!totpToken) {
      return res.json({
        needsTwoFactor: true,
        tempUserId: user.id,
        message: 'Two-Factor Authentication token required',
      });
    }

    // Verify token on server or client
    // Token checked via verifyTotpToken on client or bypass if valid backup code
    const isBackupCode = user.backupCodes && user.backupCodes.includes(totpToken.trim().toUpperCase());
    if (isBackupCode) {
      // Remove used backup code
      user.backupCodes = user.backupCodes.filter((c: string) => c !== totpToken.trim().toUpperCase());
      saveDb();
    }
  }

  user.lastSeen = Date.now();
  saveDb();

  res.json({
    user: {
      id: user.id,
      username: user.username,
      displayName: user.displayName,
      avatarColor: user.avatarColor,
      bio: user.bio,
      publicKeyJwk: user.publicKeyJwk,
      twoFactorEnabled: user.twoFactorEnabled,
      createdAt: user.createdAt,
    },
    token: `token_${user.id}_${Date.now()}`,
  });
});

// 2FA: Toggle / Update user 2FA status
app.post('/api/auth/2fa/update', (req: Request, res: Response) => {
  const { userId, enabled, secret, backupCodes } = req.body;
  const user = db.users[userId];
  if (!user) {
    return res.status(404).json({ error: 'User not found' });
  }

  user.twoFactorEnabled = !!enabled;
  if (enabled) {
    user.twoFactorSecret = secret;
    user.backupCodes = backupCodes || [];
  } else {
    user.twoFactorSecret = null;
    user.backupCodes = [];
  }

  saveDb();
  res.json({ success: true, twoFactorEnabled: user.twoFactorEnabled, backupCodes: user.backupCodes });
});

