// Create Conversation (Direct or Group)
app.post('/api/conversations', (req: Request, res: Response) => {
  const { type, name, description, participants, creatorId, disappearingTimer, groupKeyMap } = req.body;

  if (!participants || participants.length === 0) {
    return res.status(400).json({ error: 'Participants are required' });
  }

  const allParticipants = Array.from(new Set([creatorId, ...participants]));

  // If 1-on-1, check if already exists
  if (type === 'direct' && allParticipants.length === 2) {
    const existing = Object.values(db.conversations).find((c: any) => {
      return (
        c.type === 'direct' &&
        c.participants.length === 2 &&
        c.participants.includes(allParticipants[0]) &&
        c.participants.includes(allParticipants[1])
      );
    });

    if (existing) {
      return res.json(existing);
    }
  }

  const conversationId = `conv_${Math.random().toString(36).substring(2, 11)}`;
  const colors = [
    'from-emerald-500 to-teal-600',
    'from-indigo-500 to-cyan-600',
    'from-purple-500 to-pink-600',
    'from-amber-500 to-rose-600',
  ];
  const avatarColor = colors[Math.floor(Math.random() * colors.length)];

  const conversation = {
    id: conversationId,
    type: type || 'direct',
    name: name || (type === 'direct' ? 'Private Chat' : 'Secure Group'),
    description: description || '',
    avatarColor,
    participants: allParticipants,
    adminIds: [creatorId],
    createdAt: Date.now(),
    updatedAt: Date.now(),
    disappearingTimer: disappearingTimer || 0,
    groupKeyMap: groupKeyMap || {},
  };

  db.conversations[conversationId] = conversation;
  db.messages[conversationId] = [];
  saveDb();

  // Notify participants via WebSocket
  allParticipants.forEach((pId: string) => {
    sendToUser(pId, {
      type: 'conversation:new',
      data: conversation,
    });
  });

  res.json(conversation);
});

// Get User's Conversations
app.get('/api/conversations', (req: Request, res: Response) => {
  const userId = req.query.userId as string;
  if (!userId) {
    return res.status(400).json({ error: 'userId is required' });
  }

  const userConversations = Object.values(db.conversations)
    .filter((c: any) => c.participants.includes(userId))
    .map((c: any) => {
      const msgs = db.messages[c.id] || [];
      const lastMsg = msgs.length > 0 ? msgs[msgs.length - 1] : null;

      // If direct chat, populate name & avatar of the other participant
      let displayName = c.name;
      let avatarColor = c.avatarColor;
      let otherUserOnline = false;

      if (c.type === 'direct') {
        const otherId = c.participants.find((p: string) => p !== userId);
        const otherUser = otherId ? db.users[otherId] : null;
        if (otherUser) {
          displayName = otherUser.displayName;
          avatarColor = otherUser.avatarColor;
          otherUserOnline = connectedClients.has(otherId);
        }
      }

      return {
        ...c,
        name: displayName,
        avatarColor,
        isOtherUserOnline: otherUserOnline,
        lastMessage: lastMsg
          ? {
              text: lastMsg.isEncrypted ? '🔒 Encrypted message' : lastMsg.decryptedContent,
              senderId: lastMsg.senderId,
              senderDisplayName: lastMsg.senderDisplayName,
              timestamp: lastMsg.timestamp,
              status: lastMsg.status,
            }
          : null,
      };
    })
    .sort((a, b) => b.updatedAt - a.updatedAt);

  res.json(userConversations);
});

// Update Conversation Settings (Disappearing timer, name, etc.)
app.patch('/api/conversations/:id', (req: Request, res: Response) => {
  const { id } = req.params;
  const { disappearingTimer, name, description, participants, groupKeyMap } = req.body;
  const conv = db.conversations[id];
  if (!conv) {
    return res.status(404).json({ error: 'Conversation not found' });
  }

  if (disappearingTimer !== undefined) conv.disappearingTimer = disappearingTimer;
  if (name) conv.name = name;
  if (description !== undefined) conv.description = description;
  if (participants) conv.participants = participants;
  if (groupKeyMap) conv.groupKeyMap = { ...conv.groupKeyMap, ...groupKeyMap };
  conv.updatedAt = Date.now();

  saveDb();

  // Notify all participants
  conv.participants.forEach((pId: string) => {
    sendToUser(pId, {
      type: 'conversation:updated',
      data: conv,
    });
  });

  res.json(conv);
});

// Get Messages for a Conversation
app.get('/api/conversations/:id/messages', (req: Request, res: Response) => {
  const { id } = req.params;
  const msgs = db.messages[id] || [];
  const now = Date.now();

  // Filter out expired disappearing messages
  const activeMsgs = msgs.filter((m: any) => !m.disappearsAt || m.disappearsAt > now);
  if (activeMsgs.length !== msgs.length) {
    db.messages[id] = activeMsgs;
    saveDb();
  }

  res.json(activeMsgs);
});

// Send Message (Encrypted payload relay)
app.post('/api/messages/send', (req: Request, res: Response) => {
  const {
    id,
    conversationId,
    senderId,
    senderUsername,
    senderDisplayName,
    ciphertext,
    iv,
    salt,
    isEncrypted,
    type,
    fileData,
    replyTo,
    disappearingDuration,
  } = req.body;

  const conv = db.conversations[conversationId];
  if (!conv) {
    return res.status(404).json({ error: 'Conversation not found' });
  }

  const messageId = id || `msg_${Math.random().toString(36).substring(2, 11)}`;
  const duration = disappearingDuration || conv.disappearingTimer || 0;
  const disappearsAt = duration > 0 ? Date.now() + duration * 1000 : undefined;

  const newMsg = {
    id: messageId,
    conversationId,
    senderId,
    senderUsername,
    senderDisplayName,
    ciphertext,
    iv,
    salt,
    isEncrypted: isEncrypted ?? true,
    type: type || 'text',
    fileData,
    replyTo,
    timestamp: Date.now(),
    status: 'sent',
    disappearsAt,
    disappearingDuration: duration,
  };

  if (!db.messages[conversationId]) {
    db.messages[conversationId] = [];
  }
  db.messages[conversationId].push(newMsg);
  conv.updatedAt = Date.now();
  saveDb();

  // Broadcast to other participants in conversation
  conv.participants.forEach((pId: string) => {
    if (pId !== senderId) {
      const isRecipientOnline = connectedClients.has(pId);
      if (isRecipientOnline) {
        newMsg.status = 'delivered';
      }
      sendToUser(pId, {
        type: 'message:new',
        data: newMsg,
      });
    }
  });

  res.json(newMsg);
});

// Schedule Message ("Send Later")
app.post('/api/messages/schedule', (req: Request, res: Response) => {
  const messageData = req.body;
  if (!messageData.scheduledFor || messageData.scheduledFor <= Date.now()) {
    return res.status(400).json({ error: 'Scheduled time must be in the future.' });
  }

  const scheduleId = `sched_${Math.random().toString(36).substring(2, 11)}`;
  const scheduledItem = {
    ...messageData,
    id: scheduleId,
    status: 'scheduled',
    createdAt: Date.now(),
  };

  db.scheduledMessages.push(scheduledItem);
  saveDb();

  res.json(scheduledItem);
});

// Get Scheduled Messages for a user
app.get('/api/messages/scheduled', (req: Request, res: Response) => {
  const userId = req.query.userId as string;
  if (!userId) {
    return res.status(400).json({ error: 'userId required' });
  }

  const userScheduled = db.scheduledMessages.filter((m) => m.senderId === userId);
  res.json(userScheduled);
});

// Cancel Scheduled Message
app.delete('/api/messages/schedule/:id', (req: Request, res: Response) => {
  const { id } = req.params;
  const initialLength = db.scheduledMessages.length;
  db.scheduledMessages = db.scheduledMessages.filter((m) => m.id !== id);
  saveDb();

  res.json({ success: true, deleted: initialLength !== db.scheduledMessages.length });
});

// File Upload Handler (Base64 storage for 0-cost self-host)
app.post('/api/upload', (req: Request, res: Response) => {
  const { fileName, fileType, fileData, size } = req.body;
  if (!fileData) {
    return res.status(400).json({ error: 'File data missing' });
  }

  // Return file metadata and local reference
  res.json({
    success: true,
    file: {
      name: fileName || 'attachment',
      mimeType: fileType || 'application/octet-stream',
      size: size || 0,
      dataUrl: fileData,
    },
  });
});

// ==================== BACKGROUND TIMERS ====================
// Dispatch scheduled messages and purge expired disappearing messages every 3 seconds
setInterval(() => {
  const now = Date.now();

  // 1. Process Scheduled Messages
  const due = db.scheduledMessages.filter((m) => m.scheduledFor && m.scheduledFor <= now);
  if (due.length > 0) {
    db.scheduledMessages = db.scheduledMessages.filter((m) => !m.scheduledFor || m.scheduledFor > now);

    due.forEach((scheduledMsg) => {
      const conv = db.conversations[scheduledMsg.conversationId];
      if (conv) {
        const releasedMsg = {
          ...scheduledMsg,
          id: `msg_${Math.random().toString(36).substring(2, 11)}`,
          status: 'sent',
          timestamp: now,
          scheduledFor: undefined,
        };

        if (!db.messages[scheduledMsg.conversationId]) {
          db.messages[scheduledMsg.conversationId] = [];
        }
        db.messages[scheduledMsg.conversationId].push(releasedMsg);
        conv.updatedAt = now;

        // Broadcast to all participants including sender
        conv.participants.forEach((pId: string) => {
          sendToUser(pId, {
            type: 'message:new',
            data: releasedMsg,
          });
        });
      }
    });

    saveDb();
  }

  // 2. Disappearing messages cleanup
  let messagesPurged = false;
  Object.keys(db.messages).forEach((convId) => {
    const list = db.messages[convId];
    const remaining = list.filter((m) => !m.disappearsAt || m.disappearsAt > now);
    if (remaining.length !== list.length) {
      db.messages[convId] = remaining;
      messagesPurged = true;
    }
  });

  if (messagesPurged) {
    saveDb();
  }
}, 3000);

// ==================== VITE MIDDLEWARE SETUP ====================
async function startServer() {
  if (process.env.NODE_ENV !== 'production') {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: 'spa',
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*', (req: Request, res: Response) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  server.listen(PORT, '0.0.0.0', () => {
    console.log(`CipherGram E2EE server running on http://0.0.0.0:${PORT}`);
  });
}

startServer();
